import * as S from './science.js';
import {plot,fmt,esc,colors,legend} from './viz.js';
const controls=(label,id,items,value)=>`<div class="control"><label for="${id}">${label}</label><select id="${id}">${items.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></div>`;
const range=(label,id,min,max,step,value)=>`<div class="control"><label for="${id}">${label}<output for="${id}">${value}</output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
const shell=(title,inputs,body,caption,recorded=false)=>`<div class="lab"><div class="lab-heading"><strong>${title}</strong><span>${recorded?'RECORDED DATA':'LIVE TOY EXAMPLE'}</span></div><div class="lab-controls">${inputs}</div><div class="lab-body">${body}</div><div class="lab-metrics"></div><div class="lab-caption">${caption}</div></div>`;
const stats=items=>items.map(([name,value])=>`<div class="lab-metric"><span>${name}</span><strong>${typeof value==='number'?fmt(value):esc(value)}</strong></div>`).join('');
function bind(host,update){host.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{const out=host.querySelector(`output[for="${el.id}"]`);if(out)out.value=el.value;update();}));}
export function contractValues(p,fn='cube'){const x=[-1,1],w=[1-p,p],y=S.eigen1(x,w),f=fn==='mean'?v=>v:fn==='square'?v=>v*v:fn==='right'?v=>+(v>0):v=>v*v*v;return{x,w,y,target:S.scalarMoments(x,w),output:S.scalarMoments(y),original:S.sum(x.map((v,i)=>w[i]*f(v))),transformed:S.mean(y.map(f))};}
function contract(host){host.innerHTML=shell('Two particles, several probability questions',range('Target right-side probability','contract-p',.05,.95,.05,.75)+controls('Question f(x)','contract-question',[['mean','Mean: x'],['square','Second moment: x²'],['cube','Third moment: x³'],['right','Right-side event: 1{x > 0}']],'cube'),'<div id="contract-plot"></div><div class="lab-status" id="contract-reading"></div>','Teaching example · x=[−1,1], weights=[1−p,p]. Equal-weight affine output. Errors compare output answers with the weighted empirical input.');
function update(){const p=+host.querySelector('#contract-p').value,fn=host.querySelector('#contract-question').value,r=contractValues(p,fn);host.querySelector('#contract-plot').innerHTML=plot({series:[{name:'Weighted input probability',type:'scatter',points:r.x.map((x,i)=>[x,r.w[i]]),color:colors[1],radius:7},{name:'Affine output probability',type:'scatter',points:r.y.map(x=>[x,.5]),color:colors[0],radius:6}],xLabel:'Position',yLabel:'Probability mass',xDomain:[-2,2],yDomain:[0,1],height:260})+legend([['Weighted input',colors[1]],['Affine output',colors[0]]]);host.querySelector('.lab-metrics').innerHTML=stats([['Weighted answer E[f(X)]',r.original],['Affine answer E[f(Y)]',r.transformed],['Signed answer error',r.transformed-r.original],['Mean error',Math.abs(r.target.mean-r.output.mean)],['Variance error',Math.abs(r.target.variance-r.output.variance)]]);host.querySelector('#contract-reading').textContent=`Output positions: [${fmt(r.y[0],5)}, ${fmt(r.y[1],5)}], each with probability 0.5. ${fn==='mean'||fn==='square'?'This answer is fixed by the matched moments.':'This answer is not guaranteed by matching only mean and covariance.'}`;}
bind(host,update);update();}
export function metricValues(kind,p=.75,shift=.7){let x,w,y;if(kind==='shift'){x=[0,2];w=[.5,.5];y=x.map(v=>v+shift);}else{x=[-1,1];w=[1-p,p];y=kind==='collapse'?x.map(()=>S.scalarMoments(x,w).mean):S.eigen1(x,w);}const target=S.scalarMoments(x,w),output=S.scalarMoments(y);return{x,w,y,target,output,meanError:Math.abs(target.mean-output.mean),varianceError:Math.abs(target.variance-output.variance),w1:S.wasserstein1(x,w,y),mmd:S.mmd2(x,w,y),cubicError:Math.abs(S.mean(y.map(v=>v**3))-S.sum(x.map((v,i)=>w[i]*v**3)))};}
function cdf(x,w,lo,hi){const points=[[lo,0]],values=[...new Set(x)].sort((a,b)=>a-b);let mass=0;for(const value of values){points.push([value,mass]);mass+=S.sum(x.map((v,i)=>v===value?w[i]:0));points.push([value,mass]);}points.push([hi,1]);return points;}
function metricPlayground(host){host.innerHTML=shell('Which measurement detects which error?',controls('Output change','metric-kind',[['shift','Shift every point'],['eigen','Affine moment match'],['collapse','Collapse to the mean']],'shift')+range('Input right mass (affine / collapse)','metric-p',.1,.9,.05,.75)+range('Shift distance (shift case)','metric-shift',-1.5,1.5,.1,.7),'<div id="metric-cdf"></div><div class="lab-status" id="metric-reading"></div>','Teaching example · exact empirical 1D W1 and exact Gaussian-kernel MMD². MMD bandwidth is weighted input SD. The main multidimensional benchmark uses projected W1 and approximate RFF MMD².');
function update(){const kind=host.querySelector('#metric-kind').value,p=+host.querySelector('#metric-p').value,shift=+host.querySelector('#metric-shift').value,r=metricValues(kind,p,shift),all=r.x.concat(r.y),lo=Math.min(...all)-.4,hi=Math.max(...all)+.4;host.querySelector('#metric-p').disabled=kind==='shift';host.querySelector('#metric-shift').disabled=kind!=='shift';host.querySelector('#metric-cdf').innerHTML=plot({series:[{name:'Input CDF',points:cdf(r.x,r.w,lo,hi),color:colors[1]},{name:'Output CDF',points:cdf(r.y,r.y.map(()=>1/r.y.length),lo,hi),color:colors[0],dashed:true}],xLabel:'Position',yLabel:'Cumulative probability',xDomain:[lo,hi],yDomain:[0,1.05],height:285})+legend([['Input CDF',colors[1]],['Output CDF (dashed)',colors[0]]]);host.querySelector('.lab-metrics').innerHTML=stats([['Mean error',r.meanError],['Variance error',r.varianceError],['Exact 1D W1',r.w1],['Exact MMD²',r.mmd],['Cubic expectation error',r.cubicError]]);host.querySelector('#metric-reading').textContent=`W1 is the area between these CDFs. ${kind==='shift'?'A common shift preserves variance; W1 equals the absolute shift.':kind==='collapse'?'All output mass is at the input mean. Center error is zero, but uncertainty is lost.':'Mean and variance match. A nonzero shape or cubic error can remain.'} Kernel bandwidth: ${fmt(Math.sqrt(r.target.variance))}.`;}
bind(host,update);update();}
const pinned={particles:'https://github.com/nchopin/particles/tree/3388c4bd30ab9acc5a27c970089230f93610b627',cuthbert:'https://github.com/state-space-models/cuthbert/tree/c737efe3098b2b5ecaa7d8b976e7cea246998b17',stone:'https://github.com/dstl/Stone-Soup/tree/d6c2d5713b5fdc0bc0c5c0226898bc1c598a882a',pfjax:'https://github.com/mlysy/pfjax/tree/97652aa1bdff73a92c0286549b010e99cc6f7264',pydpf:'https://github.com/John-JoB/pydpf/tree/a7487ce1c344c70e1a244e75725b950deb15e146'};
const taskCards={
moments:{name:'Match mean and covariance',task:'Gaussian / fixed cloud',example:'Use [−1,1] with weights [0.25,0.75]. Check mean 0.5 and variance 0.75, then try a singular 2D cloud.',reference:'Weighted input population moments.',measure:'Mean and covariance errors. Add W1 to avoid confusing moments with shape.',source:'pfjax',path:'/src/pfjax/particle_resamplers.py',lesson:'gaussian-mixture'},
shape:{name:'Keep alternative explanations',task:'Separated mixture, then UNGM',example:'Two peaks at −3 and +3; change the right mass from 0.5 to 0.9. Next note that ±2 give the same UNGM observation mean 0.2.',reference:'Weighted input measure for the static test; simulated truth for the nonlinear filter.',measure:'Sliced W1, nonlinear expectation error, mode mass; then tracking RMSE and coverage.',source:'particles',path:'/book/resampling/compare_tv_distance_resampling.py',lesson:'gaussian-mixture'},
score:{name:'Obtain an accurate likelihood gradient',task:'Linear Gaussian / Kalman',example:'First check J(θ)=θ² at θ=2. Then compare PF likelihood scores with exact Kalman scores on the same observations.',reference:'Exact Kalman log-likelihood derivative for the stated model.',measure:'Score bias, variance, MSE; use finite differences separately for implementation checks.',source:'cuthbert',path:'/docs/examples/diff_pf_resampling.md',lesson:'linear'},
learning:{name:'Fit a parameter and preserve risk',task:'Stochastic volatility',example:'At state log(4), observation SD is twice its value at state 0. Fit an observation scale using the declared five-value grid.',reference:'True simulated scale and the stated approximate grid-filter reference.',measure:'Scale error and score RMSE; read state RMSE with uncertainty coverage.',source:'pydpf',path:'/replication_materials',lesson:'volatility'},
recovery:{name:'Recover after missing observations',task:'Bearing-only tracking with a gap',example:'(1,1) and (2,2) produce the same bearing. Remove ten observations and check how long recovery takes.',reference:'True simulated position and a declared recovery criterion.',measure:'Position RMSE, coverage, post-gap RMSE, recovery time and recovery fraction.',source:'stone',path:'/docs/examples/filters/bearing_only_example.py',lesson:'bearing'},
sampling:{name:'Reduce added sampling variation',task:'Fixed weighted cloud',example:'Repeat two-particle ancestor draws with expected counts [0.5,1.5]. Keep the input cloud unchanged.',reference:'Exact weighted expectation and expected offspring counts.',measure:'Conditional count bias/variance for copying methods; expectation MSE for all outputs.',source:'particles',path:'/particles/resampling.py',lesson:'fixed-cloud'}
};
function taskGuide(host){host.innerHTML=shell('Choose a benchmark from your question',controls('What do you need?','task-question',Object.entries(taskCards).map(([k,t])=>[k,t.name]),'moments'),'<div id="task-answer"></div>','Planning guide · illustrative inputs. Shared benchmark and native source settings remain separate.');function update(){const t=taskCards[host.querySelector('#task-question').value];host.querySelector('#task-answer').innerHTML=`<h3>${t.task}</h3><p><b>Small example:</b> ${t.example}</p><p><b>Reference:</b> ${t.reference}</p><p><b>Why these metrics:</b> ${t.measure}</p><div class="button-row"><a class="button secondary small" href="#/benchmarks/${t.lesson}">Read this task ↑</a><a class="button secondary small" href="${pinned[t.source]}${t.path}" target="_blank" rel="noopener noreferrer">Pinned source example ↗</a></div>`;}bind(host,update);update();}
async function evidenceTour(host,loadData){host.innerHTML=shell('Three questions, three evidence checks','', '<p>Loading the measured rows…</p>','Recorded benchmark data · values are loaded from the exported summary tables.',true);const data=await loadData();if(!host.isConnected)return;let step='moments';host.querySelector('.lab-controls').innerHTML=`<div class="stage-buttons" role="group" aria-label="Evidence tour">${[['moments','1 · Moments'],['shape','2 · Shape'],['score','3 · Score']].map(([v,l])=>`<button class="stage-button" data-tour="${v}" aria-pressed="false">${l}</button>`).join('')}</div>`;const rows=data.tables.static_summary.filter(r=>r.n===128&&r.dim===2&&r.cloud==='mixture'),eigen=rows.find(r=>r.provider==='custom'&&r.method==='eigen'),systematic=rows.find(r=>r.provider==='stonesoup'&&r.method==='systematic'),score=data.tables.torch_native_summary.find(r=>r.provider==='custom'&&r.method==='eigen'&&r.n===128);
function update(){host.querySelectorAll('[data-tour]').forEach(b=>{b.classList.toggle('active',b.dataset.tour===step);b.setAttribute('aria-pressed',String(b.dataset.tour===step));});let body,items;if(step==='moments'){body='<h3>Does the eigen map match the target moments?</h3><p>Shared mixture · N=128 · d=2. Reference: weighted input moments. Errors near numerical precision support this property on this full-rank cell. They do not settle shape or filtering quality.</p>';items=[['Eigen mean error',eigen.mean_error_mean],['Eigen covariance error',eigen.covariance_error_mean],['Resampling trials',eigen.trials]];}else if(step==='shape'){body='<h3>Does moment matching also preserve shape?</h3><p>Same shared mixture cell and weighted input reference. Compare sliced W1. This changes the research question while keeping the data fixed. A lower value here does not establish a universal ranking.</p>';items=[['Eigen sliced W1',eigen.sliced_w1_mean],['Stone Soup systematic W1',systematic.sliced_w1_mean],['Eigen covariance error',eigen.covariance_error_mean]];}else{body='<h3>Is the likelihood gradient accurate?</h3><p>Native linear Gaussian data · N=128. Reference: exact Kalman gradient. This is a new task layer. Read bias, variance, and MSE together; do not compare their units with static W1.</p>';items=[['Eigen score bias norm',score.gradient_bias],['Eigen score variance',score.gradient_variance],['Eigen score MSE',score.gradient_mse]];}host.querySelector('.lab-body').innerHTML=body;host.querySelector('.lab-metrics').innerHTML=stats(items);}
host.querySelectorAll('[data-tour]').forEach(button=>button.onclick=()=>{step=button.dataset.tour;update();});update();}
export function mountAdvancedLab(name,host,loadData){return({'contract':contract,'metric-playground':metricPlayground,'task-guide':taskGuide,'evidence-tour':evidenceTour}[name])?.(host,loadData);}
